    N = len(A)
    A_sum = [0] * N
    B_sum = [0] * N
    A_sum[0] = A[0]
    B_sum[0] = B[0]

    for i in range(1, N):
        A_sum[i] = A_sum[i-1] + A[i]
        B_sum[i] = B_sum[i-1] + B[i]

    dp = [[[0 for _ in range(K+1)] for _ in range(N)] for _ in range(N)]

    for i in range(N):
        dp[i][i][0] = min((A_sum[i] + B_sum[i]), min_A)
        if i + 1 < N:
            dp[i][i+1][1] = min((A_sum[i] + B_sum[i+1]), 2 * (B_sum[i]))

    for l in range(2, N):
        for i in range(N):
            j = i + l - 1
            if j < N:
                for k in range(1, K + 1):
                    max_sum = A_sum[j] + B_sum[j]
                    if i > 0:
                        max_sum = max(max_sum, dp[i-1][j-k][k-1])
                    if j > 1:
                        max_sum = max(max_sum, dp[i][j-2][k])
                    dp[i][j][k] = max_sum
    return max(dp[0][N-1])

