from collections import deque

def can_reduce_to_one(n, permutation):
    # Create a graph where each node is a unique value from the permutation
    # and add edges between nodes that appear consecutively in the permutation
    graph = {i: [] for i in range(1, n+1)}
    for i in range(len(permutation)-1):
        if permutation[i] == permutation[i+1]:
            graph[permutation[i]].append(permutation[i+1])
            graph[permutation[i+1]].append(permutation[i])

    def bfs(start):
        visited = set()
        queue = deque([start])
        visited.add(start)

        while queue:
            current = queue.popleft()
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        return all(visited)

    # Check if the graph is a tree (can be reduced to one node)
    return bfs(permutation[0])

def solve(n, permutation):
    for i in range(n):
        for j in range(i+1, n):
            if permutation[i] > permutation[j]:
                # Found an increasing pair, so we cannot reduce to one node
                return "NO"
    # Check if all elements are the same, which could be reduced to one node
    return "YES" if len(set(permutation)) == 1 else "NO"

