import sys
from math import inf
from heapq import *

def read_ints():
    return map(int, sys.stdin.readline().split())

class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.A = [0] * (n + 1)

    def increment(self, i, x):
        while i < self.n:
            self.A[i] += x
            i += i & -i

    def reduce(self, i):
        reduction = 0
        while i > 0:
            reduction += self.A[i]
            i -= i & -i
        return reduction

def solve_queries(n, q, queries):
    nums = read_ints()
    ft = FenwickTree(n)
    first_good_index, good_numbers = None, set()
    for i, num in enumerate(nums, 1):
        if num == 1:
            ft.increment(i, 1)
        elif num == 2:
            ft.increment(i, -1)
            continue
        else:
            ft.increment(i, 1)
            good_numbers.add(i)
        while good_numbers and nums[first_good_index] + 1 == nums[good_numbers[0] - 1]:
            ft.increment(good_numbers.pop(), 1)
            nums[first_good_index] += 1
        if nums[first_good_index] >= 26:
            return
        if len(good_numbers) > first_good_index:
            num = nums[good_numbers[len(good_numbers) - 1]] - nums[first_good_index] + 1
            for i in range(first_good_index + 1, len(nums)):
                if nums[first_good_index] + num <= nums[i]:
                    break
                ft.increment(i, -num)
                ft.increment(first_good_index, -1)
                first_good_index += 1
        else:
            first_good_index += 1
    for _ in range(q - n):
        query_type, a, b, x = read_ints()
        if query_type == 2:
            ft.increment(b, -1)
            ft.increment(a, 1)
        elif query_type == 3:
            ft.increment(b, -x)
            nums[b] += x
            while good_numbers and nums[first_good_index] + 1 == nums[good_numbers[0] - 1]:
