def longest_palindromic_subsequence(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for gap in range(1, n):
        for i in range(n - gap):
            j = i + gap
            if s[i] == s[j]:
                dp[i][j] = 2 + dp[i + 1][j - 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1]

def max_equal_color_pants(n, k, pants):
    max_pants = 0
    chosen_colors = set()
    for i in range(n):
        if i >= k:
            max_pants = max(max_pants, len(j) - chosen_colors.count(j[-1]) for j in chosen_colors)
        while max_pants >= 0:
            if pants[i] == pants[max_pants]:
                chosen_colors.add(pants[i])
                break
            max_pants -= 1
    return max_pants if max_pants >= 0 else -1

def solve(testcase):
    n, k = map(int, input().split())
    pants = input()
    maximum_pants = max_equal_color_pants(n, k, pants)
    return maximum_pants

