def find_min_operations(x, y, n):
    equalities = [x[i] ^ y[i] for i in range(n)]
    if any(x % 2 == 0 or y % 2 == 0 for x, y in zip(equalities, equalities)):
        return -1
    return n // 2 - min(x // 2 - y // 2 for x, y in zip(equalities, equalities))

def solve(x, y):
    n = len(x)
    answer = []
    for i in range(n):
        for j in range(n):
            if abs(x[i] ^ y[i]) < abs(x[j] ^ y[j]):
                k = find_min_operations([x] * n, [y] * n, n)
                if k == -1:
                    return []
                answer.extend([[i, k], [j, k]])
    return answer

