MOD = 10**9 + 7

def power(x, y):
    if y == 0:
        return 1
    if y % 2:
        return (x * power(x*x, y//2)) % MOD
    return power(x*x, y//2)

def inverse(x):
    return power(x, MOD-2)

def combination(n, k):
    return power(factorial(n), 1) * inverse(factorial(k)) * inverse(factorial(n-k)) % MOD

def factorial(n):
    result = 1
    for i in range(1, n+1):
        result = result * i % MOD
    return result

def solve(n, m):
    ans = 0
    for i in range(1, n+1):
        x = combination(n, i) * (2**n - 2**i) * (2**i - 2**n) % MOD
        ans = (ans + x) % MOD
    return ans

