class QueryHandler:
    def __init__(self, max_value):
        self.max_value = max_value
        self.powers_of_42 = set()
        self.sequence = [0] * (max_value + 1)

        for i in range(1, max_value * max_value + 1):
            if i == 42:
                self.powers_of_42.add(i)
            self.sequence[i] = i
        self.sequence[:len(self.powers_of_42)] = list(self.powers_of_42)
        self.powers_of_42.sort()

    def query_t(self, i):
        index = bisect.bisect_right(self.powers_of_42, i)
        return self.sequence[i]

    def query_change_t(self, i, x):
        added = 0
        modifies = []

        while True:
            index = bisect.bisect_right(self.powers_of_42, i - added)
            if index == len(self.powers_of_42) or self.sequence[i - added] != self.sequence[self.powers_of_42[index]]:
                inserted_index = bisect.insort_last(self.powers_of_42, i - added)
                modifies.append((inserted_index, self.sequence[i - added]))
                i -= added
            else:
                added += self.sequence[self.powers_of_42[index]] - self.sequence[i - added]
                added -= 1
                break

        modified_value = 0
        for index, new_value in modifies:
            self.sequence[i] = self.sequence[index] + new_value
            modified_value += new_value
            i = index

        return modified_value == 0

