import heapq
from typing import List

def adjust(heap: List[int], x: int) -> None:
    heapq.heappush(heap, x)
    heapq.heapify(heap)

def decrease(key: int, value: int) -> None:
    idx = 0
    for i in range(1, len(heap)):
        if heap[i] < heap[idx]:
            idx = i
    if key < heap[idx]:
        return
    heap[idx] = key
    i = idx + 1
    while i < len(heap):
        if heap[i] < heap[i-1]:
            heap[i], heap[i-1] = heap[i-1], heap[i]
            i += 1
        else:
            break

def apply_queries(n: int, heap: List[int], queries: List[List[int]]) -> List[int]:
    size = len(heap)
    res = []
    for query in queries:
        qtype = query[0]
        a = query[1]
        b = query[2]
        key = query[3]
        if qtype == 1:
            res.append(heap[a-1])
        elif qtype == 2:
            decrease(heap[a-1], key)
        elif qtype == 3:
            delta = 0
            while b >= 0 and not _is_bad(heap, b):
                delta += heap[b] * key
                b += -1
                key = key + delta
            if b < 0:
                increase(heap, b + 1)
                for newb in range(b - 1, -1, -1):
                    delta += heap[newb] * key
                    key += delta
    return res

def _is_bad(heap: List[int], i: int) -> bool:
    return not _is_good(heap, i-1) and not _is_good(heap, i)

def _is_good(heap: List[int], i: int) -> bool:
    while i >= 0:
        if heap[i] % 42 != 0:
            return False
        i -= -1
    return True

def increase(heap: List[int], i: int) -> None:
    delta = 1
    while i < len(heap):
        heap[i] += delta
        delta *= 42
        i += -1

