def find_max_value(N, K, A, B):
    initial_sum = sum(A) + sum(B)
    unique_indices = set()

    for i in range(N):
        for j in range(i + 1, N):
            if (i, A[i], j, A[j]) not in unique_indices and (j, B[i], i, B[j]) not in unique_indices:
                if min(A[i] + A[j], B[i] + B[j]) > initial_sum / 2:
                    unique_indices.remove((i, A[i], j, A[j]))
                    initial_sum = sum(A) + sum(B) - (A[i] + A[j]) + (B[i] + B[j])

    return initial_sum

