def modAdd(a, b):
    return (a + b) % MOD

def getModInv(n, mod):
    """Compute the modular multiplicative inverse of n modulo mod."""
    return pow(n, mod - 2, mod)

def binomial(n, k, MOD):
    """Compute (n choose k) modulo MOD using Lucas' theorem."""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    rest = (n % MOD, k % MOD)
    large = (n // MOD) % MOD
    small = (k // MOD) % MOD
    return (binomial(large, small, MOD) * binomial(rest[0], rest[1], MOD)) % MOD

def dfs(n, k, mod):
    """Dynamic Programming DFS to calculate f_p(k) for all good sequences."""
