    ops_first = 0
    ops_second = 0

    # Transform initial array into min-heap
    heapq.heapify(arr)

    dp = [[0, 0] for _ in range(size)]

    for i in range(size):
        if arr[i] <= arr[0]:
            dp[i][0] = dp[i - 1][0] + 1
        elif arr[i] < arr[size - 1]:
            dp[i][0] = dp[i - 1][0]
        else:
            dp[i][0] = float('inf')

    # Transform initial array into max-heap and lock comparison
    arr = [-x for x in arr]
    heapq.heapify(arr)

    for i in range(1, size):
        if arr[i] >= arr[i - 1]:
            dp[i][1] = dp[i - 1][1] + 1
        else:
            dp[i][1] = dp[i - 1][1]

    for i in range(size - 2, -1, -1):
        if arr[i] >= arr[i + 1]:
            dp[i][1] = min(dp[i + 1][1], dp[i][1] + 1)
        else:
            dp[i][1] = min(dp[i + 1][1], dp[i][1])

    # Add operations between min-heap and max-heap
    for i in range(1, size - 1):
        dp[i][0] += min(dp[i + 1][1] + 1, dp[i][1] + 1)
        if dp[i][0] == float('inf'):
            dp[i][0] += abs(arr[i + 1] - arr[i])

    return min(dp[-1])

