        [x - 1 for x in range(2, max_val)] +
        [x for x in range(max_val - 1, 0, -2)] +
        [max_val - 1] +
        [x + 1 for x in range(max_val) if x != max_val - 1] +
        [x - 1 for x in range(2, max_val) if x != 1]
