def calculate_modular_fibonacci(n):
    m = 998244353

    def inverse_modulo(x):
        return pow(x, m-2, m)

    A = 0
    B = 0
    for length in range(1, n+1):
        if length % 2 == 1:
            A = (A * (length + 1)) % m
        else:
            B = (B * (length + 1)) % m
        A = (A + B) % m

    return (A + m * B) % m

def solve(n):
