from itertools import combinations

def score(n, m, k):
    # Function to calculate the probability that a row or a column is completely marked
    def probability(row, col):
        events = [(i, j) for i in range(n) for j in range(row + col * n)]
        favorable = 0
        for i, j in combinations(events, k):
            if i[0] < row or j[0] < row or i[1] < col*n or j[1] < n:
                continue
            if abs(i[0] - j[0]) <= row or abs(i[1] - j[1]) <= n:
                favorable += 1
        return favorable / (m(n - 1) * m(k - 1))

    total = 0.0
    for row in range(n):
        for col in range(n):
            if row == col:
                total += 1 / (10 ** 9)
            total += probability(row, col)
