from collections import deque
from typing import List

def min_operations(arr: List[int]) -> int:
    n = len(arr)
    if n == 1:
        return 0
    elif n == 2:
        return int(arr[0] > arr[1])

    left_heap, right_heap = [], []
    heapify(left_heap)
    heapify(right_heap)

    for i in range(n):
        heappush(left_heap, -arr[i])
        heappush(right_heap, -arr[n-i-1])

        if len(left_heap) - len(right_heap) > 2:
            heappush(right_heap, -heappop(left_heap))
        elif len(right_heap) - len(left_heap) > 2:
            heappush(left_heap, -heappop(right_heap))

        if len(left_heap) > len(right_heap) + 1 or (len(left_heap) == len(right_heap) + 1 and left_heap[0] > right_heap[0]):
            heappush(right_heap, -heappop(left_heap))

    return len(right_heap)


